import{_ as o,o as a,c as s,a3 as t}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Support: OTP, devices and media","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/support.md","filePath":"dev/domain/support.md"}'),i={name:"dev/domain/support.md"};function d(n,e,r,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="support-otp-devices-and-media" tabindex="-1">Support: OTP, devices and media <a class="header-anchor" href="#support-otp-devices-and-media" aria-label="Permalink to &quot;Support: OTP, devices and media&quot;">​</a></h1><p>The <strong>Support</strong> module holds the shared building blocks.</p><h2 id="otp" tabindex="-1">OTP <a class="header-anchor" href="#otp" aria-label="Permalink to &quot;OTP&quot;">​</a></h2><p>All phone sign-in goes through <code>OtpVerificationService</code>.</p><ul><li>Codes are <strong>hashed</strong> and expire after <strong>300 seconds</strong>.</li><li>A new send invalidates older unused codes. A successful verify consumes the code.</li><li>Limits: <strong>5 sends per phone per 15 minutes</strong>, <strong>5 failed verifies per 5 minutes</strong>.</li><li>Use the same phone string for send, verify and account lookup.</li></ul><h3 id="development-bypass" tabindex="-1">Development bypass <a class="header-anchor" href="#development-bypass" aria-label="Permalink to &quot;Development bypass&quot;">​</a></h3><p>Works only when <code>otp.dev.enabled</code> is on, the environment is <code>local</code>, <code>testing</code> or <code>staging</code>, <strong>and</strong> the phone is in <code>OTP_DEV_PHONES</code>. Never widen it.</p><h2 id="devices-and-push-tokens" tabindex="-1">Devices and push tokens <a class="header-anchor" href="#devices-and-push-tokens" aria-label="Permalink to &quot;Devices and push tokens&quot;">​</a></h2><p>Register devices through <code>DeviceService::launch()</code> and link them on login with <code>attachTo()</code>. A device is unique per <code>(owner, identifier, platform)</code>. Invalid FCM tokens are <strong>nulled, not deleted</strong>.</p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><p>Uploads go to <code>POST /api/v1/media</code> (the only endpoint that accepts several guards) and become <strong>temporary uploads</strong>. Attach client-supplied media only through <code>TemporaryMediaService::promote()</code> or <code>promoteMany()</code> (owner, expiry, lock, single use; <code>promoteMany</code> is all-or-nothing). Every media failure is reported as one 422 <code>InvalidTemporaryMediaException</code>. <code>DELETE media/{uuid}</code> removes an upload.</p><h2 id="system-users-roles-cities-and-tags" tabindex="-1">System users, roles, cities and tags <a class="header-anchor" href="#system-users-roles-cities-and-tags" aria-label="Permalink to &quot;System users, roles, cities and tags&quot;">​</a></h2><p>Admin CRUD for <code>system-users</code> (with <code>restore</code>), <code>system-roles</code>, <code>system-permissions</code> (read), <code>cities</code> and <code>tags</code>. See <a href="./../conventions/permissions">Roles and permissions</a>. Every admin policy denies inactive system users.</p><h2 id="activity-log" tabindex="-1">Activity log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity log&quot;">​</a></h2><p><code>admin/activity-logs</code> shows the audit trail (<code>activity_logs.view_any</code>). Translatable attributes are logged with every locale.</p><h2 id="documentation-access" tabindex="-1">Documentation access <a class="header-anchor" href="#documentation-access" aria-label="Permalink to &quot;Documentation access&quot;">​</a></h2><p><code>/docs</code> (endpoint reference) and <code>/guide</code> (these guides) are protected by a session login at <code>/docs/login</code> for active system users with <code>api_docs.view</code>. Five failed logins in a minute return 429.</p>',17)])])}const m=o(i,[["render",d]]);export{u as __pageData,m as default};
